import { cn } from '@/lib/utils'

/**
 * Animated SVG illustration that follows the site theme.
 * Files live in /public/illustrations/codespectra as <name>-light.svg and
 * <name>-dark.svg (generated by scripts/build-landing-svgs.py). Only the one
 * matching the current theme is displayed; the other is display:none, so
 * screen readers announce the alt text once.
 */
export function ThemeIllustration({
  name,
  alt = '',
  width,
  height,
  className,
  priority = false,
}: {
  name: string
  /** Leave empty for decorative illustrations next to text that says the same thing. */
  alt?: string
  width: number
  height: number
  className?: string
  priority?: boolean
}) {
  const common = {
    alt,
    width,
    height,
    decoding: 'async' as const,
    loading: priority ? ('eager' as const) : ('lazy' as const),
    'aria-hidden': alt ? undefined : true,
  }
  return (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element -- animated SVGs must not go through the image optimizer */}
      <img src={`/illustrations/codespectra/${name}-light.svg`} {...common} className={cn('block h-auto dark:hidden', className)} />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={`/illustrations/codespectra/${name}-dark.svg`} {...common} className={cn('hidden h-auto dark:block', className)} />
    </>
  )
}
